"""Two service-business demos: local stay planning and class selection."""
from pathlib import Path
import json,html
R=Path(__file__).resolve().parent;D=R/'dist';DATA=json.loads((R/'concepts-content.json').read_text(encoding='utf8'))
def esc(s):return html.escape(str(s),quote=True)
def bi(en,ar,tag='span',attrs=''):return f'<{tag} data-en="{esc(en)}" data-ar="{esc(ar)}" {attrs}>{esc(en)}</{tag}>'
def image(slug,name,alt,lazy=True):return f'<img src="/assets/concepts/{slug}/{name}" alt="{esc(alt)}" width="1536" height="1024" loading="{"lazy" if lazy else "eager"}">'
for slug in ['dar-saha','paceform']:
 b=DATA[slug];stay=slug=='dar-saha';asset='/assets/concepts/'+slug+'/'
 style=';'.join('--'+key+':'+b[value] for key,value in [('dark','dark'),('light','light'),('accent','accent'),('paper','white'),('ink','ink'),('display','display')])
 page=f'''<!doctype html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{b['name']} | {b['kind']}</title><meta name="description" content="{esc(b['intro'])}"><meta name="robots" content="noindex,follow"><link rel="canonical" href="https://digitsstudio.online/demos/{slug}/"><link rel="icon" href="{asset}symbol.svg"><link rel="stylesheet" href="/assets/concepts/concepts.css"><link rel="stylesheet" href="/assets/concepts/experiences.css"></head><body class="experience {slug}" style="{style}"><a class="skip" href="#demo-main">{bi('Skip to content','تخطّي إلى المحتوى')}</a><div class="demo-notice">{bi('A fictional brand, thoughtfully made by Digits Studio.','علامة خيالية صُمّمت بعناية من ديجيتس ستوديو.')}<a data-case href="/projects/{slug}/">{bi('Explore the project','استكشف المشروع')}</a></div><header class="experience-header"><a href="#demo-main"><img src="{asset}logo-primary.svg" alt="{b['name']}" width="210" height="83"></a><nav><a href="#collection">{bi('The rooms' if stay else 'The timetable','الغرف' if stay else 'الجدول')}</a><a href="#story">{bi('The feeling' if stay else 'The studio','الأجواء' if stay else 'الاستوديو')}</a></nav><div><button type="button" class="experience-language" aria-label="Read in Arabic">عربي</button><a class="action" href="{'#stay-planner' if stay else '#collection'}">{bi('Plan a stay' if stay else 'Find a class','خطّط لإقامتك' if stay else 'اختر حصتك')}</a></div></header><main id="demo-main">'''
 if stay:
  page+=f'''<section class="stay-hero"><div><h1>{bi(b['headline'],b['arHeadline'])}</h1><p>{bi(b['intro'],b['arIntro'])}</p></div>{image(slug,'hero.webp','Dar Saha fictional guesthouse terrace',False)}</section><section class="stay-planner" id="stay-planner"><div><h2>{bi('A few days,\nyour own way.','أيام قليلة،\nعلى طريقتك.')}</h2><p>{bi('Put together a sample stay. No availability check or reservation is made.','جهّز إقامة تجريبية. لا يُفحص التوفّر ولا يُنشأ حجز.')}</p></div><form id="stay-form"><div class="planner-fields"><label>{bi('Arrival','الوصول')}<input type="date" name="arrival" required></label><label>{bi('Nights','الليالي')}<select name="nights">{''.join(f'<option value="{i}">{i}</option>' for i in [1,2,3,4,5,6,7,10,14])}</select></label><label>{bi('Guests','الضيوف')}<select name="guests"><option value="1">1</option><option value="2" selected>2</option></select></label><label>{bi('Your room','غرفتك')}<select name="room">{''.join(f'<option value="{room["id"]}" data-en="{room["name"]}" data-ar="{room["ar"]}">{room["name"]}</option>' for room in b['rooms'])}</select></label></div><button class="action" type="submit">{bi('Create a sample stay plan','جهّز خطة إقامة تجريبية')}</button><div id="stay-result" class="experience-result" hidden role="status" aria-live="polite"></div></form></section><section class="rooms-section" id="collection"><div class="experience-heading"><h2>{bi('Room to settle in.','مساحة لتستريح.')}</h2><p>{bi('Two ways to make yourself at home. Sample room rates in USD, per night.','طريقتان لتشعر أنك في بيتك. أسعار توضيحية بالدولار لليلة الواحدة.')}</p></div><div class="rooms-grid">'''
  for room in b['rooms']:
   page+=f'''<article class="room-card">{image(slug,room['image'],room['name'])}<div><p class="room-meta"><bdi>{room['size']}</bdi> / {bi('up to 2 guests','حتى ضيفين')}</p><h3>{bi(room['name'],room['ar'])}</h3><p>{bi(room['description'],room['arDescription'])}</p><p><bdi>${room['price']}</bdi> {bi('/ sample night','/ لليلة التجريبية')}</p><div class="actions"><button class="room-detail" type="button" data-room="{room['id']}">{bi('Explore the room','استكشف الغرفة')}</button><button class="room-select action" type="button" data-room="{room['id']}">{bi('Choose this room','اختر هذه الغرفة')}</button></div></div></article>'''
  page+='</div></section>'
 else:
  page+=f'''<section class="pace-hero"><div><h1>{bi(b['headline'],b['arHeadline'])}</h1><p>{bi(b['intro'],b['arIntro'])}</p><a class="action" href="#collection">{bi('Find your first class','اختر حصتك الأولى')}</a></div>{image(slug,'hero.webp','Paceform fictional strength studio',False)}</section><section class="pace-principle"><h2>{bi('Different starting points.\nA shared momentum.','بدايات مختلفة.\nحركة تجمعنا.')}</h2><p>{bi('Choose a session by the movement, the time and how it fits your week. Clear information, without the pressure.','اختر حصتك بحسب الحركة والوقت وما يناسب أسبوعك. معلومات واضحة، دون ضغط.')}</p></section><section class="schedule-section" id="collection"><div class="experience-heading"><h2>{bi('Make space\nin your week.','مساحة للحركة\nضمن أسبوعك.')}</h2><p>{bi('An illustrative weekly timetable. Session selection is a local demo, with no reservation or payment.','جدول أسبوعي توضيحي. الاختيار تجربة محلية دون حجز أو دفع.')}</p></div><div class="class-filters" role="group" aria-label="Movement types">'''
  for i,(key,en,ar) in enumerate([('all','All movement','كل الحصص'),('strength','Strength','القوة'),('mobility','Mobility','المرونة'),('reformer','Reformer','الريفورمر')]):page+=f'<button type="button" data-class-filter="{key}" aria-pressed="{str(i==0).lower()}">{bi(en,ar)}</button>'
  page+='</div><div class="schedule-list">'
  for cls in b['classes']:
   page+=f'''<article class="session-row" data-class-type="{cls['type']}"><div class="session-time"><strong>{bi(cls['day'],cls['arDay'])}</strong><bdi>{cls['time']}</bdi></div><div><h3>{bi(cls['name'],cls['ar'])}</h3><p>{bi(cls['description'],cls['arDescription'])}</p></div><p class="session-meta"><bdi>{cls['duration']}</bdi> {bi('min','دقيقة')}<br><bdi>${cls['price']}</bdi> {bi('sample session','لجلسة تجريبية')}</p><button type="button" class="action session-detail" data-session="{cls['id']}">{bi('View session','عرض الحصة')}</button></article>'''
  page+=f'''</div><div id="session-result" class="experience-result" hidden role="status" aria-live="polite"></div><button id="clear-session" class="clear-session" type="button" hidden>{bi('Clear selection','إلغاء الاختيار')}</button></section>'''
 page+=f'''<section class="experience-story" id="story">{image(slug,'room.webp' if stay else 'studio.webp',b['name']+' fictional interior')}<div><h2>{bi(b['storyTitle'],b['arStoryTitle'])}</h2><p>{bi(b['story'],b['arStory'])}</p><a data-case href="/projects/{slug}/">{bi('Discover the brand behind the experience','اكتشف الهوية وراء التجربة')}</a></div></section><section class="experience-end"><h2>{bi('A slower day starts here.' if stay else 'One useful next step.','هنا يبدأ يوم أهدأ.' if stay else 'خطوة واضحة إلى الأمام.')}</h2><a class="action" href="/concepts/{slug}/welcome-email.html">{bi('Preview the welcome email','معاينة رسالة الترحيب')}</a></section></main><footer class="demo-footer"><img src="{asset}logo-reverse.svg" alt="{b['name']}" width="230" height="90"><div><p>{bi('A self-initiated concept by Digits Studio.','مشروع تصوّري من ديجيتس ستوديو.')}</p><p class="small">{bi('Fictional business, generated photography and illustrative prices. No real reservations, memberships, payments or personal-data submissions.','علامة خيالية وتصوير مولّد وأسعار توضيحية. لا حجوزات أو اشتراكات أو مدفوعات أو إرسال بيانات شخصية.')}</p><a data-case href="/projects/{slug}/">{bi('Back to the project','العودة إلى المشروع')}</a></div></footer><dialog id="experience-dialog" aria-labelledby="experience-dialog-title"><div class="modal-heading"><h2 id="experience-dialog-title"></h2><button class="dialog-close" type="button" aria-label="Close dialog">×</button></div><div id="experience-dialog-content"></div></dialog><script id="experience-data" type="application/json">{json.dumps(dict(b,slug=slug),ensure_ascii=False)}</script><script src="/assets/concepts/experiences.js" defer></script></body></html>'''
 folder=D/'demos'/slug;folder.mkdir(exist_ok=True,parents=True);(folder/'index.html').write_text(page,encoding='utf8')
print('Dar Saha stay planner and Paceform class timetable built.')
